import { ChangeDetectionStrategy, Component, computed, inject, input } from '@angular/core';
import { CONTENT_PROVIDER } from '../../core/content/content-provider.token';
import { FaqSection } from '../../core/content/content.models';
import { InlineTextComponent } from '../ui/inline-text.component';
import { SectionHeadingComponent } from './section-heading.component';
import { SectionComponent } from './section.component';

/**
 * FAQ accordion: native details/summary, works without JavaScript (brief 4.6). FAQPage JSON-LD
 * is generated by SeoService from the same faq.json entries. The CRA footnote is shown
 * directly under any block that contains C1 or C2.
 */
@Component({
  selector: 'app-faq-section',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [SectionComponent, SectionHeadingComponent, InlineTextComponent],
  styles: `
    .faq { max-width: 52rem; }
    .faq summary { font-size: var(--fs-h4); }
    .faq__answer { padding: 0 0 var(--space-5); }
    .faq__answer p { margin: 0; }
  `,
  template: `
    @let s = section();
    <app-section [sectionId]="s.id" [tone]="s.tone">
      <app-section-heading [sectionId]="s.id" [heading]="s.heading" />
      <div class="faq">
        @for (item of items(); track item.id) {
          <details class="disclosure" [id]="'faq-' + item.id">
            <summary>{{ item.question }}</summary>
            <div class="faq__answer"><p><app-text [text]="item.answer" /></p></div>
          </details>
        }
      </div>
      @if (footnote(); as note) {
        <p class="footnote">{{ note }}</p>
      }
    </app-section>
  `,
})
export class FaqSectionComponent {
  readonly section = input.required<FaqSection>();
  private readonly content = inject(CONTENT_PROVIDER);
  protected readonly items = computed(() => this.content.faq(this.section().faqIds));
  protected readonly footnote = computed(() => this.items().find((i) => i.footnote)?.footnote);
}
